import { useMemo } from 'react';
import { WorkspaceApp, createWebWorkspaceHost, createWebStorageAdapter, migrateLegacyCellWorkspace } from '@sue/verd-board-app';
import '@sue/verd-board-ui/style.css';
export function App() {
  const host = useMemo(() => createWebWorkspaceHost(), []);
  return <WorkspaceApp host={host} importLegacy={async () => {
    const adapter = createWebStorageAdapter();
    return (await adapter.listKeys()).length ? migrateLegacyCellWorkspace(adapter) : null;
  }} />;
}

import { useState } from 'react';
import { createCellRegistry } from '@sue/board-core';
import { createMindFrameSnapshot } from '@sue/board-mind';
import { FrameCanvas } from '@sue/board-react';
import { createMindFrameExtensions } from '@sue/board-react-mind';
import '@sue/board-react-text/style.css';
const registry = createCellRegistry();
const extensions = createMindFrameExtensions(registry);
export function MindEditor() {
  const [value, setValue] = useState(() => createMindFrameSnapshot('frame', 'root'));
  return <div style={{height: 600}}><FrameCanvas registry={registry} extensions={extensions} value={value} onChange={({snapshot}) => setValue(snapshot)} /></div>;
}

import { applyCellOperations, type FrameSnapshot } from '@sue/board-core';
import { FrameCanvas, type FrameCanvasProps } from '@sue/board-react';
import { useState } from 'react';
export function HostEditor({ initial }: { initial: FrameSnapshot }) {
  const [value, setValue] = useState({ snapshot: initial });
  const props: FrameCanvasProps<typeof value> = {
    value, adapter: { toFrameSnapshot: v => v.snapshot },
    onIntent: transaction => {
      const store = applyCellOperations(value.snapshot.store, transaction.operations);
      setValue({ snapshot: { store } });
      return { status: 'accepted' };
    },
  };
  return <div style={{height: 600}}><FrameCanvas {...props} /></div>;
}

import { useState } from 'react';
import { createBlockText } from '@sue/board-common';
import { DocumentEditor } from '@sue/board-react-text';
import '@sue/board-react-text/style.css';
export function Editor() {
  const [value, setValue] = useState(() => createBlockText('Hello'));
  return <DocumentEditor value={value} onChange={change => setValue(change.value)} />;
}

import { createCellRegistry } from '@sue/board-core';
import { createUmlClassFrameSnapshot } from '@sue/board-uml';
import { FrameCanvas } from '@sue/board-react';
import { createUmlFrameExtensions } from '@sue/board-react-uml';
import '@sue/board-react-text/style.css';
const registry = createCellRegistry();
const extensions = createUmlFrameExtensions(registry);
const value = createUmlClassFrameSnapshot('frame', 'uml-root');
export function Preview() {
  return <div style={{height: 600}}><FrameCanvas readonly value={value} registry={registry} extensions={extensions} /></div>;
}

import { parseMarkdownToTextDocument, serializeTextDocumentToMarkdown } from '@sue/board-markdown-to-text';
const { document, warnings } = parseMarkdownToTextDocument('# Title\n\nBody', { id: 'doc' });
const result = serializeTextDocumentToMarkdown(document);
console.log(result.markdown, warnings, result.warnings);

import { parseMermaidToFrameSnapshot, serializeFrameToMermaid } from '@sue/board-mermaid-to-board';
export async function convert() {
  const snapshot = await parseMermaidToFrameSnapshot('classDiagram\nclass User', { scene: 'uml-class' });
  return serializeFrameToMermaid(snapshot);
}

